// Package prompt is the single source of truth for the prompts neokapi sends to
// an LLM.
//
// A prompt is an input to a build: it must be deterministic (the same inputs
// render the same bytes), inspectable (see kapi's --explain), and versioned (a
// changed prompt must not serve output generated by an older one from cache).
// Prompts therefore live here rather than being inlined at each call site —
// they were previously duplicated across the translate tool's streaming,
// inline-code and batch paths plus the provider layer, and had drifted apart.
//
// Prompts are provider-neutral. They declare roles semantically as Turns; the
// aiprovider layer is responsible for transporting a Turn the way each vendor's
// API expects (Anthropic lifts system into a top-level parameter, Gemini folds
// it into the first user turn, OpenAI carries it as an ordinary message). No
// prompt in this package branches on the provider.
package prompt

// Version identifies the revision of the prompts in this package. It is folded
// into the AI tool config fingerprint, so bumping it re-translates rather than
// serving cached output that an older prompt produced.
//
// Bump it whenever the rendered bytes of any prompt below change.
const Version = "v2"

// Role names a Turn's speaker. These mirror aiprovider's role constants; this
// package deliberately does not import aiprovider, so that aiprovider can
// import it.
const (
	RoleSystem = "system"
	RoleUser   = "user"
)

// Turn is one message of a rendered prompt.
type Turn struct {
	Role string
	Text string
}

// System builds a system turn.
func System(text string) Turn { return Turn{Role: RoleSystem, Text: text} }

// User builds a user turn.
func User(text string) Turn { return Turn{Role: RoleUser, Text: text} }
